//#region lib/backend/queries.ts
const id = z.string().uuid();
const empty = z.object({}).strict();
const page = z.number().int().min(1).max(1e4).default(1);
const list = z.object({
	q: z.string().max(80).default(""),
	page
});
function query(schema, run) {
	return {
		schema,
		async run(ctx, input) {
			const parsed = schema.safeParse(input);
			if (!parsed.success) throw new BackendError(400, "INVALID_QUERY", parsed.error.issues[0]?.message ?? "Sorgu geçersiz.");
			return run(ctx, parsed.data);
		}
	};
}
function check(result) {
	if (result.error) throw new BackendError(503, "DATA_UNAVAILABLE", "Veriler yüklenemedi.");
	return result;
}
function rpcData(result) {
	if (result.error) throw new BackendError(result.error.code === "42501" ? 403 : 503, result.error.code === "42501" ? "FORBIDDEN" : "DATA_UNAVAILABLE", dbErrorMessage(result.error, "Veriler yüklenemedi."));
	return result.data;
}
const queries = {
	session: query(empty, async (ctx) => ({
		userId: ctx.userId,
		email: ctx.email,
		profile: ctx.profile
	})),
	workspace: query(requestSchema, listWorkspaceSection),
	"members.list": query(list.strict(), async (ctx, v) => {
		requireBackendRole(ctx, ["admin"]);
		const { data, error } = await ctx.supabase.from("centers").select("id,organization_id");
		if (error) throw new BackendError(503, "DATA_UNAVAILABLE", "Merkezler yüklenemedi.");
		return check(await listMembers(ctx.supabase, {
			q: sanitizeSearchTerm(v.q),
			page: v.page,
			centerIds: managedCenters(data ?? [], ctx.profile.assignments).map((c) => c.id)
		}));
	}),
	"members.account": query(centerAccountSchema, lookupCenterAccount),
	"lessons.list": query(list.extend({ status: z.union([z.enum(LESSON_STATUSES), z.literal("")]).default("") }).strict(), async (ctx, v) => {
		requireBackendRole(ctx, ["admin", "instructor"]);
		return check(await listLessons(ctx.supabase, {
			...v,
			q: sanitizeSearchTerm(v.q)
		}));
	}),
	"subscriptions.list": query(list.extend({ status: z.union([z.enum(SUBSCRIPTION_STATUSES), z.literal("")]).default("") }).strict(), async (ctx, v) => {
		requireBackendRole(ctx, ["admin"]);
		return check(await listSubscriptions(ctx.supabase, {
			...v,
			q: sanitizeSearchTerm(v.q)
		}));
	}),
	"attendance.list": query(list.extend({ lessonId: z.union([id, z.literal("")]).default("") }).strict(), async (ctx, v) => {
		requireBackendRole(ctx, [
			"admin",
			"instructor",
			"ainstructor"
		]);
		return check(await listAttendance(ctx.supabase, {
			...v,
			q: sanitizeSearchTerm(v.q)
		}));
	}),
	"credits.list": query(list.strict(), async (ctx, v) => {
		requireBackendRole(ctx, ["admin"]);
		return check(await listTransactions(ctx.supabase, {
			...v,
			q: sanitizeSearchTerm(v.q)
		}));
	}),
	"requests.list": query(z.object({ page }).strict(), async (ctx, v) => {
		requireBackendRole(ctx, ["admin", "instructor"]);
		const [from, to] = pageRange(v.page);
		const { data, count, error } = await ctx.supabase.from("session_requests").select("*", { count: "exact" }).order("created_at", { ascending: false }).order("id").range(from, to);
		return {
			rows: rpcData({
				data,
				error
			}),
			total: count ?? 0
		};
	}),
	"requests.members": query(z.object({ centerId: id }).strict(), (ctx, v) => listRequestableMembers(ctx, v.centerId)),
	planning: query(reportRange, async (ctx, v) => {
		requireBackendRole(ctx, ["admin"]);
		return rpcData(await ctx.supabase.rpc("planning_workspace", {
			p_from: v.from,
			p_to: v.to
		}));
	}),
	reports: query(reportRange, async (ctx, v) => {
		requireBackendRole(ctx, ["admin"]);
		return rpcData(await ctx.supabase.rpc("studio_report", {
			p_from: v.from,
			p_to: v.to
		}));
	}),
	insights: query(reportRange, async (ctx, v) => {
		requireBackendRole(ctx, ["admin"]);
		return rpcData(await ctx.supabase.rpc("roadmap_workspace", {
			p_module: "insights",
			p_from: v.from,
			p_to: v.to
		}));
	}),
	policies: query(empty, async (ctx) => {
		requireBackendRole(ctx, ["admin"]);
		return rpcData(await ctx.supabase.rpc("policy_workspace"));
	}),
	"subscriptions.eligibility": query(z.object({ lessonId: id }).strict(), async (ctx, v) => {
		requireBackendRole(ctx, [
			"admin",
			"instructor",
			"ainstructor"
		]);
		return rpcData(await ctx.supabase.rpc("lesson_package_eligibility", { p_lesson: v.lessonId }));
	}),
	"subscriptions.stats": query(empty, async (ctx) => {
		requireBackendRole(ctx, ["admin"]);
		return rpcData(await ctx.supabase.rpc("subscription_stats"));
	}),
	"account.registration": query(empty, async (ctx) => rpcData(await ctx.supabase.rpc("registration_self_workspace"))),
	"account.packages": query(empty, async (ctx) => rpcData(await ctx.supabase.rpc("my_subscription_terms"))),
	"account.balances": query(empty, async (ctx) => rpcData(await ctx.supabase.rpc("my_payment_balances"))),
	"instructor.lessons": query(empty, async (ctx) => {
		requireBackendRole(ctx, [
			"instructor",
			"ainstructor",
			"admin"
		]);
		return rpcData(await ctx.supabase.rpc("my_teaching_lessons"));
	}),
	"instructor.roster": query(z.object({ lessonId: id }).strict(), async (ctx, v) => {
		requireBackendRole(ctx, [
			"instructor",
			"ainstructor",
			"admin"
		]);
		return rpcData(await ctx.supabase.rpc("my_lesson_roster", { p_lesson_id: v.lessonId }));
	}),
	notifications: query(z.object({ page }).strict(), async (ctx, v) => {
		const [from, to] = pageRange(v.page);
		const { data, count, error } = await ctx.supabase.from("notifications").select("*", { count: "exact" }).eq("recipient_id", ctx.userId).order("created_at", { ascending: false }).order("id").range(from, to);
		return {
			rows: rpcData({
				data,
				error
			}),
			total: count ?? 0
		};
	})
};
function getQuery(name) {
	if (!Object.hasOwn(queries, name)) throw new BackendError(404, "NOT_FOUND", "Sorgu bulunamadı.");
	return queries[name];
}
function queryParameters(url) {
	const values = {};
	for (const [key, value] of url.searchParams) {
		if (Object.hasOwn(values, key)) throw new BackendError(400, "INVALID_QUERY", "Tekrarlanan sorgu parametresi.");
		if (key === "page") values[key] = /^\d+$/.test(value) ? Number(value) : value;
		else if (key === "ascending") values[key] = value === "true" ? true : value === "false" ? false : value;
		else if (key === "filters") try {
			values[key] = JSON.parse(value);
		} catch {
			throw new BackendError(400, "INVALID_QUERY", "Filtre geçerli JSON olmalı.");
		}
		else values[key] = value;
	}
	return values;
}
//#endregion
//#region lib/backend/openapi.ts
function schemaFor(schema) {
	const { $schema, ...json } = z.toJSONSchema(schema, {
		io: "input",
		unrepresentable: "any"
	});
	return json;
}
const errors = {
	type: "object",
	required: [
		"ok",
		"error",
		"requestId"
	],
	properties: {
		ok: { const: false },
		error: {
			type: "object",
			required: ["code", "message"],
			properties: {
				code: { type: "string" },
				message: { type: "string" }
			}
		},
		requestId: {
			type: "string",
			format: "uuid"
		}
	}
};
const success = {
	type: "object",
	required: [
		"ok",
		"data",
		"requestId"
	],
	properties: {
		ok: { const: true },
		data: {},
		requestId: {
			type: "string",
			format: "uuid"
		}
	}
};
function responses() {
	return Object.fromEntries([
		200,
		400,
		401,
		403,
		404,
		405,
		409,
		413,
		415,
		422,
		500,
		503
	].map((code) => [code, {
		description: code === 200 ? "Success" : "API error",
		content: { "application/json": { schema: code === 200 ? success : errors } }
	}]));
}
function openApiDocument(baseUrl = "https://ysplylnwdfwizmuxvcqg.supabase.co/functions/v1/studio-api") {
	const paths = {};
	for (const [name, command] of Object.entries(commands)) paths[`/v1/commands/${name}`] = { post: {
		operationId: name.replaceAll(".", "_"),
		tags: [name.split(".")[0]],
		security: [{ supabaseBearer: [] }],
		requestBody: {
			required: true,
			content: { "application/json": { schema: schemaFor(command.schema) } }
		},
		responses: responses()
	} };
	for (const [name, query] of Object.entries(queries)) {
		const schema = schemaFor(query.schema);
		paths[`/v1/queries/${name}`] = { get: {
			operationId: `read_${name.replaceAll(".", "_")}`,
			tags: [name.split(".")[0]],
			security: [{ supabaseBearer: [] }],
			parameters: Object.entries(schema.properties ?? {}).map(([key, value]) => ({
				name: key,
				in: "query",
				required: schema.required?.includes(key) ?? false,
				...key === "filters" ? { content: { "application/json": { schema: value } } } : { schema: value }
			})),
			responses: responses()
		} };
	}
	return {
		openapi: "3.1.0",
		info: {
			title: "StudioSaaS Edge API",
			version: "1.0.0",
			description: "Shared backend for web, Android, iOS, macOS and Windows. Use a Supabase user access token. CRUD and read RPCs are also available directly through the RLS-protected Data API. Response data is operation-specific; typed native response models require the documented database types."
		},
		servers: [{ url: baseUrl }],
		paths,
		components: { securitySchemes: { supabaseBearer: {
			type: "http",
			scheme: "bearer",
			bearerFormat: "Supabase JWT"
		} } }
	};
}
//#endregion
//#region lib/backend/router.ts
/** Standard Request/Response only: no cookies, React, or Next.js runtime. */
function createBackendHandler(config, authenticate) {
	return async (request) => {
		const url = new URL(request.url);
		const path = url.pathname.replace(/^\/(?:functions\/v1\/)?studio-api(?=\/|$)/, "");
		if (path === "/v1/openapi" && request.method === "GET") try {
			return Response.json(openApiDocument(`${config.url}/functions/v1/studio-api`), { headers: corsHeaders(request, config) });
		} catch (error) {
			if (!(error instanceof BackendError)) throw error;
			const requestId = crypto.randomUUID();
			return Response.json({
				ok: false,
				error: {
					code: error.code,
					message: error.message
				},
				requestId
			}, {
				status: error.status,
				headers: {
					"Cache-Control": "no-store",
					Vary: "Origin",
					"X-Request-Id": requestId
				}
			});
		}
		return apiResponse(request, async (context) => {
			const match = path.match(/^\/v1\/(commands|queries)\/([a-z][a-z0-9.-]*)$/);
			if (!match) throw new BackendError(404, "NOT_FOUND", "API adresi bulunamadı.");
			const [, kind, name] = match;
			const method = kind === "commands" ? "POST" : "GET";
			if (request.method !== method) throw new BackendError(405, "METHOD_NOT_ALLOWED", `${method} gerekli.`);
			return kind === "commands" ? getCommand(name).run(context, await readJsonBody(request)) : getQuery(name).run(context, queryParameters(url));
		}, config, authenticate);
	};
}
//#endregion
//#region supabase/functions/studio-api/entry.ts
const handler = createBackendHandler({
	url: Deno.env.get("SUPABASE_URL") ?? "",
	publishableKey: Deno.env.get("SUPABASE_PUBLISHABLE_KEY") ?? Deno.env.get("SUPABASE_ANON_KEY") ?? "",
	allowedOrigins: (Deno.env.get("STUDIO_API_ALLOWED_ORIGINS") ?? "https://uye.fethiyetango.com").split(",").map((origin) => origin.trim()).filter(Boolean)
});
Deno.serve(handler);
